JS_CONTENT = "(() => {\n  'use strict';\n\n  const root = document.getElementById('elfoIntroV3');\n  if (!root) return;\n\n  const leftPanel = root.querySelector('.elfo-v3-left');\n  const rightPanel = root.querySelector('.elfo-v3-right');\n  const actor = root.querySelector('#elfoV3Character');\n  const flip = actor.querySelector('.elfo-v3-flip');\n  const sheet = actor.querySelector('.elfo-v3-sheet');\n  const shadow = actor.querySelector('.elfo-v3-shadow');\n  const puller = root.querySelector('#elfoV3Puller');\n  const visual = actor.querySelector('.elfo-v3-visual');\n\n  document.documentElement.classList.add('elfo-intro-active');\n\n  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;\n  const BASE_ART_FACES_LEFT = true;\n  const TAU = Math.PI * 2;\n  const clamp = (n, a, b) => Math.min(b, Math.max(a, n));\n  const lerp = (a, b, t) => a + (b - a) * t;\n  const smoothstep = t => t * t * (3 - 2 * t);\n  const easeInOutCubic = t => t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;\n  const easeOutCubic = t => 1 - Math.pow(1 - t, 3);\n  const easeOutQuint = t => 1 - Math.pow(1 - t, 5);\n\n  let state = 'boot';\n  let x = 0;\n  let y = 0;\n  let vx = 0;\n  let targetX = 0;\n  let autoDir = 1;\n  let pointerX = innerWidth * .75;\n  let pointerSeen = false;\n  let lastPointerAt = 0;\n  let lastTime = performance.now();\n  let gaitPhase = 0;\n  let lastFrame = -1;\n  let lastHopAt = 0;\n  let sequenceToken = 0;\n  let idleSeed = Math.random() * TAU;\n\n  function actorSize() {\n    const r = actor.getBoundingClientRect();\n    return { w: r.width || 132, h: r.height || 176 };\n  }\n\n  function groundY() {\n    const { h } = actorSize();\n    return innerHeight - h - Math.max(16, innerHeight * .027);\n  }\n\n  function setFrame(frame) {\n    frame = clamp(frame | 0, 0, 3);\n    if (frame === lastFrame) return;\n    lastFrame = frame;\n    sheet.style.transform = `translate3d(${-frame * 25}%,0,0)`;\n  }\n\n  function setFacing(dir) {\n    if (Math.abs(dir) < .01) return;\n    const face = BASE_ART_FACES_LEFT ? (dir > 0 ? -1 : 1) : (dir > 0 ? 1 : -1);\n    flip.style.setProperty('--elfo-face', String(face));\n  }\n\n  function setPos(nx, ny) {\n    x = nx;\n    y = ny;\n    actor.style.transform = `translate3d(${x.toFixed(2)}px,${y.toFixed(2)}px,0)`;\n  }\n\n  function setBody(bob = 0, tilt = 0, sx = 1, sy = 1) {\n    visual.style.setProperty('--elfo-bob', `${bob.toFixed(2)}px`);\n    visual.style.setProperty('--elfo-tilt', `${tilt.toFixed(2)}deg`);\n    visual.style.setProperty('--elfo-sx', sx.toFixed(4));\n    visual.style.setProperty('--elfo-sy', sy.toFixed(4));\n  }\n\n  function idlePose(now) {\n    const t = now * .0019 + idleSeed;\n    const breath = Math.sin(t);\n    const sway = Math.sin(t * .53) * .32;\n    setFrame(0);\n    setBody(-.65 - breath * .55, sway, 1 + breath * .0028, 1 - breath * .0028);\n    shadow.style.transform = `scaleX(${(1 + breath * .012).toFixed(3)})`;\n    shadow.style.opacity = '.52';\n  }\n\n  function walkingPose(delta, speed) {\n    const stride = clamp(30 - Math.abs(speed) * .018, 22, 29);\n    gaitPhase = (gaitPhase + (Math.abs(delta) / stride) * TAU) % TAU;\n\n    // Four drawn frames, but body motion interpolates every RAF so the walk no longer feels stepped.\n    const phase01 = (gaitPhase / TAU + .03) % 1;\n    const frame = Math.floor(phase01 * 4) % 4;\n    setFrame(frame);\n\n    const footLift = Math.abs(Math.sin(gaitPhase));\n    const side = Math.sin(gaitPhase * .5);\n    const speed01 = clamp(Math.abs(speed) / 245, 0, 1);\n    const bob = -(.8 + footLift * (2.2 + speed01 * 1.35));\n    const tilt = clamp(-speed / 245 * 1.15 + side * .22, -1.45, 1.45);\n    const compress = Math.cos(gaitPhase * 2) * .0055 * speed01;\n    setBody(bob, tilt, 1 - compress, 1 + compress);\n\n    shadow.style.transform = `scaleX(${(1 - footLift * (.055 + speed01 * .035)).toFixed(3)})`;\n    shadow.style.opacity = String(.54 - footLift * .055);\n  }\n\n  function setMoving(moving, running = false) {\n    actor.classList.toggle('is-moving', moving);\n    actor.classList.toggle('is-running', running && moving);\n  }\n\n  function hop() {\n    const now = performance.now();\n    if (state !== 'roam' || now - lastHopAt < 1100) return;\n    lastHopAt = now;\n    actor.classList.remove('is-hopping');\n    void actor.offsetWidth;\n    actor.classList.add('is-hopping');\n    setTimeout(() => actor.classList.remove('is-hopping'), reduceMotion ? 180 : 620);\n  }\n\n  function updateRoam(now) {\n    const dt = Math.min(.032, Math.max(.001, (now - lastTime) / 1000));\n    lastTime = now;\n    const { w } = actorSize();\n    y = groundY();\n\n    const pointerActive = pointerSeen && now - lastPointerAt < 4200;\n    const leftBound = Math.max(16, innerWidth * .052);\n    const rightBound = Math.max(leftBound, innerWidth - w - Math.max(16, innerWidth * .052));\n\n    if (pointerActive) {\n      targetX = clamp(pointerX - w * .5, 10, innerWidth - w - 10);\n    } else if (Math.abs(targetX - x) < 15 || targetX < leftBound - 1 || targetX > rightBound + 1) {\n      autoDir *= -1;\n      targetX = autoDir > 0 ? rightBound : leftBound;\n    }\n\n    const dx = targetX - x;\n    const deadZone = pointerActive ? 7 : 11;\n    let desiredV = 0;\n    if (Math.abs(dx) > deadZone) {\n      const maxSpeed = pointerActive ? 228 : 96;\n      const minSpeed = pointerActive ? 42 : 38;\n      const distanceSpeed = Math.sqrt(Math.abs(dx)) * (pointerActive ? 14.5 : 8.6);\n      desiredV = Math.sign(dx) * clamp(distanceSpeed, minSpeed, maxSpeed);\n    }\n\n    // Exponential velocity smoothing gives a small amount of inertia without floaty overshoot.\n    const responsiveness = desiredV === 0 ? 10.5 : (Math.sign(desiredV) === Math.sign(vx) ? 7.6 : 12.0);\n    const blend = 1 - Math.exp(-responsiveness * dt);\n    vx = lerp(vx, desiredV, blend);\n    if (Math.abs(vx) < 2.2 && desiredV === 0) vx = 0;\n\n    let delta = vx * dt;\n    if (desiredV !== 0 && Math.sign(delta) === Math.sign(dx) && Math.abs(delta) > Math.abs(dx)) {\n      delta = dx;\n      vx = 0;\n    }\n\n    x = clamp(x + delta, 8, innerWidth - w - 8);\n    const moving = Math.abs(vx) > 7 && Math.abs(delta) > .02;\n    setMoving(moving, Math.abs(vx) > 165);\n\n    if (moving) {\n      setFacing(vx);\n      walkingPose(delta, vx);\n    } else {\n      idlePose(now);\n    }\n    setPos(x, y);\n  }\n\n  function loop(now) {\n    if (state === 'roam') updateRoam(now);\n    requestAnimationFrame(loop);\n  }\n\n  function animate(ms, update, easing = t => t) {\n    if (reduceMotion) ms = Math.min(ms, 220);\n    return new Promise(resolve => {\n      const start = performance.now();\n      const tick = now => {\n        const raw = clamp((now - start) / ms, 0, 1);\n        update(easing(raw), raw);\n        raw < 1 ? requestAnimationFrame(tick) : resolve();\n      };\n      requestAnimationFrame(tick);\n    });\n  }\n\n  async function walkTo(destX, speed = 275) {\n    const startX = x;\n    const distance = destX - startX;\n    const absDistance = Math.abs(distance);\n    if (absDistance < 2) return;\n\n    setFacing(distance);\n    setMoving(true, speed > 190);\n    const duration = clamp(absDistance / speed * 1000, 360, 1700);\n    let prev = startX;\n\n    await animate(duration, (p, raw) => {\n      const nx = startX + distance * p;\n      const step = nx - prev;\n      prev = nx;\n      const pseudoSpeed = Math.abs(step) / Math.max(.008, duration / 1000 / 60) * (raw < .12 ? .72 : 1);\n      x = nx;\n      y = groundY();\n      walkingPose(step, Math.sign(distance) * clamp(pseudoSpeed, 70, speed));\n      setPos(x, y);\n    }, easeInOutCubic);\n\n    vx = 0;\n    setMoving(false);\n    idlePose(performance.now());\n  }\n\n  async function enterStage() {\n    state = 'entering';\n    const { w } = actorSize();\n    y = groundY();\n    x = -w - 32;\n    actor.style.opacity = '0';\n    setPos(x, y);\n    setFacing(1);\n\n    await animate(280, p => {\n      actor.style.opacity = String(easeOutCubic(p));\n    }, t => t);\n\n    const entryX = clamp(innerWidth * .11, 24, Math.max(24, innerWidth - w - 24));\n    actor.style.opacity = '1';\n    await walkTo(entryX, 155);\n\n    targetX = clamp(innerWidth * .76, 20, innerWidth - w - 20);\n    autoDir = 1;\n    lastTime = performance.now();\n    state = 'roam';\n  }\n\n  async function leapToZipper(token) {\n    const { w } = actorSize();\n    const sx = x;\n    const sy = y;\n    const ex = innerWidth / 2 - w / 2;\n    const ey = Math.max(8, innerHeight * .018);\n\n    // Anticipation: tiny crouch before the jump.\n    await animate(190, p => {\n      if (token !== sequenceToken) return;\n      const e = easeOutCubic(p);\n      setBody(lerp(0, 4.8, e), 0, lerp(1, 1.045, e), lerp(1, .925, e));\n      shadow.style.transform = `scaleX(${lerp(1, 1.10, e)})`;\n    });\n\n    setFrame(2);\n    await animate(920, (p, raw) => {\n      if (token !== sequenceToken) return;\n      const e = easeInOutCubic(p);\n      x = lerp(sx, ex, e);\n      const linearY = lerp(sy, ey, e);\n      const arc = Math.sin(Math.PI * raw) * Math.min(164, innerHeight * .19);\n      y = linearY - arc;\n      setPos(x, y);\n\n      const lift = Math.sin(Math.PI * raw);\n      const lean = Math.sin(Math.PI * raw) * (ex >= sx ? -2.0 : 2.0);\n      setBody(-lift * 2.0, lean, 1 - lift * .018, 1 + lift * .024);\n      shadow.style.transform = `scaleX(${1 - lift * .56})`;\n      shadow.style.opacity = String(.53 - lift * .39);\n      actor.style.opacity = String(1 - Math.max(0, raw - .86) * 7.1);\n    }, easeOutQuint);\n  }\n\n  function updatePanelCut(sliderY, gapPx) {\n    const yy = Math.round(sliderY);\n    const gap = Math.round(gapPx);\n    leftPanel.style.clipPath = `polygon(0 0,calc(50% - ${gap}px) 0,50% ${yy}px,50% 100%,0 100%)`;\n    rightPanel.style.clipPath = `polygon(calc(50% + ${gap}px) 0,100% 0,100% 100%,50% 100%,50% ${yy}px)`;\n    root.style.setProperty('--zip-y', `${yy}px`);\n    root.style.setProperty('--zip-gap', `${gap}px`);\n  }\n\n  async function pullZipper(token) {\n    root.classList.add('is-pulling');\n    actor.style.opacity = '0';\n    puller.style.opacity = '1';\n    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));\n\n    const rect = puller.getBoundingClientRect();\n    const pw = rect.width || 210;\n    const ph = rect.height || pw;\n    const startY = Math.max(-8, innerHeight * .001);\n    const endY = Math.max(170, innerHeight - ph * .72 - 24);\n    const anchorX = innerWidth / 2 - pw * .815;\n    updatePanelCut(0, 0);\n\n    await animate(2050, (p, raw) => {\n      if (token !== sequenceToken) return;\n      const e = easeInOutCubic(p);\n      const py = lerp(startY, endY, e);\n      const sliderY = clamp(py + pw * .12, 0, innerHeight);\n      const gapGrowth = smoothstep(clamp((e - .05) / .95, 0, 1));\n      const gap = gapGrowth * Math.min(178, innerWidth * .118);\n      const micro = Math.sin(raw * Math.PI * 8) * (1 - raw) * .72;\n\n      puller.style.left = `${anchorX}px`;\n      puller.style.top = `${py}px`;\n      puller.style.transform = `rotate(${micro}deg)`;\n      updatePanelCut(sliderY, gap);\n    });\n  }\n\n  async function beginSequence() {\n    if (state !== 'roam') return;\n    state = 'sequence';\n    root.classList.add('is-sequencing');\n    pointerSeen = false;\n    vx = 0;\n\n    const token = ++sequenceToken;\n    const { w } = actorSize();\n    await walkTo(innerWidth / 2 - w / 2, 285);\n    if (token !== sequenceToken) return;\n\n    await new Promise(r => setTimeout(r, reduceMotion ? 20 : 110));\n    await leapToZipper(token);\n    if (token !== sequenceToken) return;\n\n    await new Promise(r => setTimeout(r, reduceMotion ? 10 : 55));\n    await pullZipper(token);\n    if (token !== sequenceToken) return;\n\n    root.classList.add('is-opening');\n    puller.style.transition = 'opacity 320ms ease, transform 620ms cubic-bezier(.16,.84,.24,1)';\n    puller.style.opacity = '0';\n    puller.style.transform += ' translateY(28px) scale(.95)';\n\n    await new Promise(r => setTimeout(r, reduceMotion ? 260 : 1120));\n    document.documentElement.classList.remove('elfo-intro-active');\n    root.hidden = true;\n    state = 'done';\n  }\n\n  document.addEventListener('pointermove', e => {\n    if (state !== 'roam') return;\n    pointerSeen = true;\n    pointerX = e.clientX;\n    lastPointerAt = performance.now();\n  }, { passive: true });\n\n  actor.addEventListener('pointerenter', hop);\n  actor.addEventListener('click', beginSequence);\n  actor.addEventListener('keydown', e => {\n    if (e.key === 'Enter' || e.key === ' ') {\n      e.preventDefault();\n      beginSequence();\n    }\n  });\n\n  addEventListener('resize', () => {\n    if (state === 'done') return;\n    const { w } = actorSize();\n    x = clamp(x, -w - 40, innerWidth - w - 8);\n    y = groundY();\n    setPos(x, y);\n  }, { passive: true });\n\n  requestAnimationFrame(() => {\n    setFrame(0);\n    setFacing(1);\n    requestAnimationFrame(loop);\n    enterStage();\n  });\n})();\n"
CSS_CONTENT = "/* Royal Jeans — Elfo Denim Intro V4 / cinematic 4K-ready rendering */\nhtml.elfo-intro-active,\nhtml.elfo-intro-active body { overflow: hidden !important; }\n\n#elfoIntroV3 {\n  position: fixed;\n  inset: 0;\n  z-index: 2147483000;\n  overflow: hidden;\n  direction: ltr;\n  user-select: none;\n  touch-action: none;\n  background:\n    radial-gradient(ellipse at 50% 26%, rgba(20,38,52,.78), transparent 54%),\n    linear-gradient(180deg, #091725 0%, #06111c 58%, #030a11 100%);\n  isolation: isolate;\n  --zip-y: 0px;\n  --zip-gap: 0px;\n}\n#elfoIntroV3[hidden] { display: none !important; }\n\n.elfo-v3-reveal {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  pointer-events: none;\n  background:\n    radial-gradient(ellipse at 50% 31%, rgba(255,211,122,.22), transparent 21%),\n    radial-gradient(ellipse at 50% 44%, rgba(80,172,229,.10), transparent 42%),\n    linear-gradient(180deg, rgba(8,18,26,.03), rgba(0,0,0,.34));\n  opacity: .52;\n  transform: translateZ(0);\n}\n\n.elfo-v3-panel {\n  position: absolute;\n  inset: -3px;\n  z-index: 5;\n  background-image:\n    repeating-linear-gradient(8deg, rgba(255,255,255,.018) 0 1px, rgba(0,0,0,.015) 1px 3px, transparent 3px 6px),\n    repeating-linear-gradient(98deg, rgba(4,18,32,.035) 0 1px, rgba(255,255,255,.012) 1px 2px, transparent 2px 5px),\n    linear-gradient(90deg, rgba(0,8,15,.10), transparent 18%, transparent 82%, rgba(0,8,15,.10)),\n    url('/static/denim-zip-v3.png?v=3');\n  background-position: center, center, center, center;\n  background-repeat: repeat, repeat, no-repeat, no-repeat;\n  background-size: auto, auto, cover, cover;\n  filter: saturate(1.07) contrast(1.06) brightness(.94);\n  transform: translateZ(0);\n  backface-visibility: hidden;\n  will-change: clip-path, transform, filter;\n  transition:\n    transform 1120ms cubic-bezier(.72,0,.18,1),\n    filter 680ms ease;\n}\n.elfo-v3-panel::before {\n  content: '';\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  opacity: .48;\n  background:\n    repeating-linear-gradient(45deg, rgba(255,255,255,.015) 0 1px, transparent 1px 4px),\n    repeating-linear-gradient(-45deg, rgba(0,0,0,.019) 0 1px, transparent 1px 4px);\n  mix-blend-mode: overlay;\n}\n.elfo-v3-panel::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  background:\n    radial-gradient(ellipse at 50% 10%, rgba(255,255,255,.11), transparent 34%),\n    radial-gradient(ellipse at 50% 108%, rgba(0,0,0,.31), transparent 54%),\n    linear-gradient(112deg, transparent 23%, rgba(255,255,255,.027) 43%, transparent 61%);\n  mix-blend-mode: screen;\n}\n.elfo-v3-left { clip-path: polygon(0 0,50% 0,50% 100%,0 100%); transform-origin: 0 50%; }\n.elfo-v3-right { clip-path: polygon(50% 0,100% 0,100% 100%,50% 100%); transform-origin: 100% 50%; }\n#elfoIntroV3.is-opening .elfo-v3-left {\n  transform: translate3d(-106%,0,0) rotate(-.42deg) scaleX(1.012);\n  filter: brightness(.70) saturate(.96);\n}\n#elfoIntroV3.is-opening .elfo-v3-right {\n  transform: translate3d(106%,0,0) rotate(.42deg) scaleX(1.012);\n  filter: brightness(.70) saturate(.96);\n}\n\n.elfo-v3-open-light {\n  position: absolute;\n  z-index: 4;\n  top: 0;\n  left: 50%;\n  width: max(2px, calc(var(--zip-gap) * 1.9));\n  height: var(--zip-y);\n  transform: translateX(-50%);\n  pointer-events: none;\n  background: linear-gradient(90deg, transparent, rgba(255,224,164,.12), transparent);\n  box-shadow:\n    0 0 18px 5px rgba(255,203,111,.30),\n    0 0 58px 17px rgba(62,168,230,.13);\n  opacity: 0;\n  transition: opacity 180ms ease;\n  filter: blur(.15px);\n}\n#elfoIntroV3.is-pulling .elfo-v3-open-light { opacity: 1; }\n\n.elfo-v3-vignette {\n  position: absolute;\n  inset: 0;\n  z-index: 9;\n  pointer-events: none;\n  box-shadow:\n    inset 0 0 min(12vw,220px) rgba(0,4,10,.73),\n    inset 0 -90px 125px rgba(0,0,0,.27);\n  transition: opacity 560ms ease;\n}\n#elfoIntroV3.is-opening .elfo-v3-vignette { opacity: 0; }\n\n.elfo-v3-brand {\n  position: absolute;\n  top: clamp(18px,2.2vh,30px);\n  left: clamp(18px,2vw,34px);\n  z-index: 14;\n  color: rgba(238,232,207,.62);\n  font: 800 clamp(8px,.58vw,11px)/1.2 system-ui,sans-serif;\n  letter-spacing: .25em;\n  text-shadow: 0 2px 9px rgba(0,0,0,.82);\n  pointer-events: none;\n}\n.elfo-v3-brand::before {\n  content: '';\n  display: inline-block;\n  width: clamp(20px,1.5vw,28px);\n  height: 1px;\n  margin-right: 8px;\n  vertical-align: middle;\n  background: rgba(224,181,91,.60);\n}\n\n.elfo-v3-character {\n  position: absolute;\n  z-index: 30;\n  width: clamp(104px,8.8vw,164px);\n  aspect-ratio: 543/724;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  outline: 0;\n  background: transparent;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  transform: translate3d(0,0,0);\n  backface-visibility: hidden;\n  will-change: transform, opacity;\n}\n.elfo-v3-character:focus-visible {\n  outline: 2px solid rgba(235,193,99,.95);\n  outline-offset: 7px;\n  border-radius: 16px;\n}\n.elfo-v3-shadow {\n  position: absolute;\n  z-index: 0;\n  left: 13%;\n  right: 13%;\n  bottom: -1.3%;\n  height: 6.8%;\n  border-radius: 50%;\n  background: rgba(0,0,0,.51);\n  filter: blur(5.4px);\n  transform-origin: center;\n  will-change: transform, opacity;\n  pointer-events: none;\n}\n.elfo-v3-flip {\n  position: absolute;\n  inset: 0;\n  z-index: 2;\n  transform: scaleX(var(--elfo-face,1));\n  transform-origin: 50% 88%;\n  will-change: transform;\n}\n.elfo-v3-visual {\n  --elfo-bob: 0px;\n  --elfo-tilt: 0deg;\n  --elfo-sx: 1;\n  --elfo-sy: 1;\n  position: absolute;\n  inset: 0;\n  transform: translate3d(0,var(--elfo-bob),0) rotate(var(--elfo-tilt)) scale(var(--elfo-sx),var(--elfo-sy));\n  transform-origin: 50% 92%;\n  backface-visibility: hidden;\n  will-change: transform;\n}\n.elfo-v3-frame-window {\n  position: absolute;\n  inset: 0;\n  overflow: hidden;\n  pointer-events: none;\n  filter: drop-shadow(0 8px 7px rgba(0,0,0,.37));\n  transform: translateZ(0);\n}\n.elfo-v3-sheet {\n  position: absolute;\n  top: 0;\n  left: 0;\n  display: block;\n  width: 400%;\n  max-width: none !important;\n  height: 100%;\n  object-fit: fill;\n  image-rendering: auto;\n  transform: translate3d(0,0,0);\n  transform-origin: 0 0;\n  backface-visibility: hidden;\n  will-change: transform;\n  pointer-events: none;\n  user-select: none;\n  -webkit-user-drag: none;\n}\n.elfo-v3-character.is-moving .elfo-v3-frame-window { filter: drop-shadow(0 9px 8px rgba(0,0,0,.40)); }\n.elfo-v3-character.is-running .elfo-v3-frame-window { filter: drop-shadow(0 11px 10px rgba(0,0,0,.44)); }\n.elfo-v3-character.is-hopping .elfo-v3-visual { animation: elfoV4Hop 610ms cubic-bezier(.18,.80,.20,1); }\n.elfo-v3-character.is-hopping .elfo-v3-shadow { animation: elfoV4ShadowHop 610ms cubic-bezier(.18,.80,.20,1); }\n\n.elfo-v3-puller {\n  position: absolute;\n  z-index: 35;\n  width: clamp(158px,15.2vw,252px);\n  height: auto;\n  display: none;\n  opacity: 0;\n  pointer-events: none;\n  image-rendering: auto;\n  filter: drop-shadow(0 15px 13px rgba(0,0,0,.44));\n  transform-origin: 81.5% 8.5%;\n  backface-visibility: hidden;\n  will-change: left, top, transform, opacity;\n}\n#elfoIntroV3.is-pulling .elfo-v3-puller { display: block; }\n\n.elfo-v3-hint {\n  position: absolute;\n  z-index: 16;\n  left: 50%;\n  bottom: clamp(15px,2.1vh,28px);\n  transform: translateX(-50%);\n  color: rgba(238,240,241,.64);\n  font: 650 clamp(10px,.68vw,12px)/1.4 system-ui,sans-serif;\n  letter-spacing: .025em;\n  text-shadow: 0 2px 9px rgba(0,0,0,.82);\n  pointer-events: none;\n  opacity: 0;\n  animation: elfoV4HintIn .78s 1.35s ease forwards;\n  transition: opacity 220ms ease;\n}\n#elfoIntroV3.is-sequencing .elfo-v3-hint { opacity: 0 !important; }\n\n@keyframes elfoV4Hop {\n  0%   { transform: translate3d(0,var(--elfo-bob),0) rotate(var(--elfo-tilt)) scale(1); }\n  13%  { transform: translate3d(0,4px,0) rotate(0) scale(1.045,.925); }\n  42%  { transform: translate3d(0,-34px,0) rotate(-1.2deg) scale(.985,1.028); }\n  67%  { transform: translate3d(0,-15px,0) rotate(.45deg) scale(1.004,.995); }\n  83%  { transform: translate3d(0,2px,0) rotate(0) scale(1.022,.975); }\n  100% { transform: translate3d(0,var(--elfo-bob),0) rotate(var(--elfo-tilt)) scale(1); }\n}\n@keyframes elfoV4ShadowHop {\n  0%,100% { transform: scaleX(1); opacity: .53; }\n  43%     { transform: scaleX(.56); opacity: .21; }\n  82%     { transform: scaleX(1.05); opacity: .48; }\n}\n@keyframes elfoV4HintIn {\n  from { opacity: 0; transform: translate(-50%,8px); filter: blur(3px); }\n  to   { opacity: .67; transform: translate(-50%,0); filter: blur(0); }\n}\n\n@media (min-width: 2200px) {\n  .elfo-v3-character { width: clamp(140px,5.3vw,190px); }\n  .elfo-v3-puller { width: clamp(210px,8.3vw,286px); }\n}\n@media (max-width: 700px) {\n  .elfo-v3-character { width: clamp(92px,24vw,126px); }\n  .elfo-v3-puller { width: clamp(144px,39vw,198px); }\n  .elfo-v3-brand { top: 15px; left: 15px; font-size: 8px; }\n  .elfo-v3-hint { bottom: 13px; font-size: 10px; width: 90%; text-align: center; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .elfo-v3-panel { transition-duration: 280ms; }\n  .elfo-v3-hint { animation-duration: .2s; animation-delay: .1s; }\n  .elfo-v3-character.is-hopping .elfo-v3-visual,\n  .elfo-v3-character.is-hopping .elfo-v3-shadow { animation-duration: 180ms; }\n}\n"


def find_root(start: Path) -> Path:
    candidates = [start, *start.parents]
    for p in candidates:
        if (p / 'frontend' / 'index.html').exists() and (p / 'backend').exists():
            return p
    for p in start.iterdir() if start.exists() else []:
        if p.is_dir() and (p / 'frontend' / 'index.html').exists() and (p / 'backend').exists():
            return p
    raise FileNotFoundError('ریشه پروژه پیدا نشد. فایل را کنار پوشه‌های frontend و backend قرار بده.')


def main():
    root = find_root(Path.cwd().resolve())
    frontend = root / 'frontend'
    css_path = frontend / 'elfo-intro-v3.css'
    js_path = frontend / 'elfo-intro-v3.js'
    index_path = frontend / 'index.html'

    for p in (css_path, js_path, index_path):
        if not p.exists():
            raise FileNotFoundError(f'فایل لازم پیدا نشد: {p}')

    stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    backup = root / f'_elfo_intro_backup_{stamp}'
    backup.mkdir(parents=True, exist_ok=False)
    shutil.copy2(css_path, backup / css_path.name)
    shutil.copy2(js_path, backup / js_path.name)
    shutil.copy2(index_path, backup / index_path.name)

    css_path.write_text(CSS_CONTENT, encoding='utf-8')
    js_path.write_text(JS_CONTENT, encoding='utf-8')

    html = index_path.read_text(encoding='utf-8')
    # Only bust the cache for the two intro files. No dashboard/tool markup is changed.
    import re
    html2 = re.sub(r'(/static/elfo-intro-v3\.css\?v=)\d+', r'\g<1>4', html)
    html2 = re.sub(r'(/static/elfo-intro-v3\.js\?v=)\d+', r'\g<1>4', html2)
    if html2 == html:
        # Safe fallback if the query string was removed manually.
        html2 = html.replace('/static/elfo-intro-v3.css', '/static/elfo-intro-v3.css?v=4')
        html2 = html2.replace('/static/elfo-intro-v3.js', '/static/elfo-intro-v3.js?v=4')
    index_path.write_text(html2, encoding='utf-8')

    print('✅ انیمیشن شروع Elfo با نسخه طبیعی‌تر و 4K-ready جایگزین شد.')
    print('✅ فقط فایل‌های Intro تغییر کردند؛ منطق ابزارها و دکمه‌ها دست نخورده است.')
    print(f'✅ بکاپ: {backup.name}')
    print('ℹ️ اگر uvicorn با --reload اجراست، صفحه را Hard Refresh کن؛ در غیر این صورت سرور را Restart کن.')


if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        print(f'❌ {e}', file=sys.stderr)
        raise
